468	fn parse_range(input_range: &str) -> Result<RangeInclusive<usize>, String> {
469	    if let Some((from, to)) = input_range.split_once('-') {
470	        let begin = from
471	            .parse::<usize>()
472	            .map_err(|_| format!("invalid input range: {}", from.quote()))?;
473	        let end = to
474	            .parse::<usize>()
475	            .map_err(|_| format!("invalid input range: {}", to.quote()))?;
476	        if begin <= end || begin == end + 1 {
477	            Ok(begin..=end)
478	        } else {
479	            Err(format!("invalid input range: {}", input_range.quote()))
480	        }
481	    } else {
482	        Err(format!("invalid input range: {}", input_range.quote()))
483	    }
484	}
