486	fn parse_head_count(headcounts: Vec<String>) -> Result<usize, String> {
487	    let mut result = usize::MAX;
488	    for count in headcounts {
489	        match count.parse::<usize>() {
490	            Ok(pv) => result = std::cmp::min(result, pv),
491	            Err(_) => return Err(format!("invalid line count: {}", count.quote())),
492	        }
493	    }
494	    Ok(result)
495	}
